function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 3 | 8)).toString(16);
  });
}
const VEHICLES = [['BUS-DEMO-01', 'ramp-node-01'], ['BUS-DEMO-02', 'ramp-node-02']];
const expected = {};
const out = [];
for (const pair of VEHICLES) {
  const vehicleId = pair[0];
  const nodeId = pair[1];
  const sessionId = uuid();
  const runId = uuid();
  expected[nodeId] = sessionId;
  flow.set('sim_' + vehicleId, { nodeId: nodeId, vehicleId: vehicleId, sessionId: sessionId, sequence: 0, stowed: true, deployed: false, steps: [], cut: false, last: null, prev: null });
  flow.set('proj_' + vehicleId, { runId: runId, projectionSequence: 1 });
  flow.set('ingest_' + nodeId, undefined);
  out.push({
    topic: 'vehicles/' + vehicleId + '/ramp/state',
    payload: { schemaVersion: 3, vehicleId: vehicleId, projectionRunId: runId, projectionSequence: 1, sourceSequence: 0, position: 'UNKNOWN', quality: 'STALE' }
  });
}
flow.set('expected', expected);
return [out];

const VEHICLES = { 'BUS-DEMO-01': 'ramp-node-01', 'BUS-DEMO-02': 'ramp-node-02' };
const vehicleId = msg.vehicleId;
const nodeId = VEHICLES[vehicleId];
const s = flow.get('sim_' + vehicleId);
if (!nodeId || !s) { return null; }

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 3 | 8)).toString(16);
  });
}
function toMsg(sample) {
  return { topic: 'telemetry/vehicles/' + vehicleId + '/ramp', payload: sample };
}
function fresh(stowed, deployed) {
  s.stowed = stowed;
  s.deployed = deployed;
  s.sequence += 1;
  const sample = {
    schemaVersion: 3, nodeId: nodeId, vehicleId: vehicleId, sessionId: s.sessionId,
    sequence: s.sequence, sourceMode: 'SIMULATED', stowedLimit: stowed, deployedLimit: deployed
  };
  s.prev = s.last;
  s.last = sample;
  return toMsg(sample);
}

const out = [];
const events = [];
const cmd = msg.cmd;
if (cmd === 'cut') {
  s.cut = !s.cut;
} else if (cmd === 'restart') {
  s.sessionId = uuid();
  s.sequence = 0;
  s.stowed = true;
  s.deployed = false;
  s.steps = [];
  s.cut = false;
  s.last = null;
  s.prev = null;
  const expected = flow.get('expected') || {};
  expected[nodeId] = s.sessionId;
  flow.set('expected', expected);
  flow.set('ingest_' + nodeId, undefined);
  events.push({ topic: vehicleId, payload: 'restart' });
} else if (!s.cut) {
  if (cmd === 'tick') {
    if (s.steps.length > 0) {
      const next = s.steps.shift();
      out.push(fresh(next[0], next[1]));
    } else {
      out.push(fresh(s.stowed, s.deployed));
    }
  } else if (cmd === 'normal') {
    if (s.stowed && !s.deployed) { s.steps = [[false, false], [false, true]]; }
    else if (!s.stowed && s.deployed) { s.steps = [[false, false], [true, false]]; }
    else { s.steps = [[false, true]]; }
    const first = s.steps.shift();
    out.push(fresh(first[0], first[1]));
  } else if (cmd === 'incomplete') {
    s.steps = [];
    out.push(fresh(false, false));
  } else if (cmd === 'contradiction') {
    s.steps = [];
    out.push(fresh(true, true));
  } else if (cmd === 'duplicate') {
    if (s.last) { out.push(toMsg(s.last)); }
  } else if (cmd === 'out_of_order') {
    if (s.prev) { out.push(toMsg(s.prev)); }
  }
}

flow.set('sim_' + vehicleId, s);
node.status({ fill: s.cut ? 'red' : 'green', shape: 'dot', text: vehicleId + (s.cut ? ' CUT' : ' seq ' + s.sequence) });
return [out.length > 0 ? out : null, events.length > 0 ? events : null];

msg.cmd = msg.payload;
msg.vehicleId = flow.get('target') || 'BUS-DEMO-01';
return msg;

const NODES = { 'BUS-DEMO-01': 'ramp-node-01', 'BUS-DEMO-02': 'ramp-node-02' };
const expected = flow.get('expected');
if (!expected) { return null; }

function freshState() {
  return { lastSeq: 0, age: 0, hasSample: false, stowed: false, deployed: false, position: 'UNKNOWN', quality: 'STALE', sincePublish: 0, discards: { schema: 0, session: 0, duplicate: 0, order: 0 } };
}
function getState(nodeId) {
  return flow.get('ingest_' + nodeId) || freshState();
}
function derive(st) {
  if (!st.hasSample || st.age >= 15) { return ['UNKNOWN', 'STALE']; }
  if (st.stowed && st.deployed) { return ['UNKNOWN', 'INVALID']; }
  if (st.stowed) { return ['STOWED', 'VALID']; }
  if (st.deployed) { return ['DEPLOYED', 'VALID']; }
  return ['INTERMEDIATE', 'VALID'];
}
function publish(vehicleId, nodeId, st) {
  const p = flow.get('proj_' + vehicleId);
  if (!p) { return null; }
  const d = derive(st);
  st.position = d[0];
  st.quality = d[1];
  st.sincePublish = 0;
  p.projectionSequence += 1;
  flow.set('proj_' + vehicleId, p);
  flow.set('ingest_' + nodeId, st);
  return { topic: 'vehicles/' + vehicleId + '/ramp/state', payload: { schemaVersion: 3, vehicleId: vehicleId, projectionRunId: p.runId, projectionSequence: p.projectionSequence, sourceSequence: st.lastSeq, position: st.position, quality: st.quality } };
}

const out = [];
const events = [];

if (msg.kind === 'tick') {
  for (const vehicleId in NODES) {
    const nodeId = NODES[vehicleId];
    const st = getState(nodeId);
    if (st.hasSample) { st.age += 1; }
    st.sincePublish += 1;
    const d = derive(st);
    if (d[0] !== st.position || d[1] !== st.quality || st.sincePublish >= 5) {
      const m = publish(vehicleId, nodeId, st);
      if (m) { out.push(m); }
    } else {
      flow.set('ingest_' + nodeId, st);
    }
  }
} else if (msg.payload === 'restart') {
  const nodeId = NODES[msg.topic];
  if (nodeId) {
    const m = publish(msg.topic, nodeId, freshState());
    if (m) { out.push(m); }
  }
} else if (typeof msg.topic === 'string' && msg.topic.indexOf('telemetry/vehicles/') === 0) {
  const topicVehicle = msg.topic.split('/')[2];
  const nodeId = NODES[topicVehicle];
  let s = msg.payload;
  if (typeof s === 'string') {
    try { s = JSON.parse(s); } catch (e) { s = null; }
  }
  // The physical node shares the vehicle topic; the projection only uses the simulator.
  if (nodeId && s !== null && typeof s === 'object' && s.sourceMode === 'PHYSICAL' && s.nodeId !== nodeId) { return null; }
  const discard = function (reason) {
    if (nodeId) {
      const st0 = getState(nodeId);
      st0.discards[reason] += 1;
      flow.set('ingest_' + nodeId, st0);
    }
    events.push({ topic: msg.topic, payload: { discarded: reason, sample: s } });
  };
  const wellFormed = s !== null && typeof s === 'object' && s.schemaVersion === 3 &&
    typeof s.nodeId === 'string' && typeof s.vehicleId === 'string' && typeof s.sessionId === 'string' &&
    Number.isInteger(s.sequence) && s.sequence > 0 && typeof s.sourceMode === 'string' &&
    typeof s.stowedLimit === 'boolean' && typeof s.deployedLimit === 'boolean';
  if (!nodeId || !wellFormed || s.vehicleId !== topicVehicle || s.nodeId !== nodeId) {
    discard('schema');
  } else if (s.sessionId !== expected[nodeId]) {
    discard('session');
  } else {
    const st = getState(nodeId);
    if (s.sequence === st.lastSeq) {
      discard('duplicate');
    } else if (s.sequence < st.lastSeq) {
      discard('order');
    } else {
      st.lastSeq = s.sequence;
      st.age = 0;
      st.hasSample = true;
      st.stowed = s.stowedLimit;
      st.deployed = s.deployedLimit;
      const d = derive(st);
      if (d[0] !== st.position || d[1] !== st.quality) {
        const m = publish(topicVehicle, nodeId, st);
        if (m) { out.push(m); }
      } else {
        flow.set('ingest_' + nodeId, st);
      }
    }
  }
}
return [out.length > 0 ? out : null, events.length > 0 ? events : null];

const p = msg.payload;
if (!p || typeof p !== 'object' || !p.vehicleId) { return null; }
const text = p.position + ' · ' + p.quality +
    ' · projection ' + p.projectionSequence + ' (sample ' + p.sourceSequence + ')' +
    ' · run ' + String(p.projectionRunId).slice(0, 8) +
    ' · received ' + new Date().toLocaleTimeString('es-ES', { timeZone: 'Europe/Madrid' });
if (p.vehicleId === 'BUS-DEMO-01') { return [{ payload: text }, null]; }
if (p.vehicleId === 'BUS-DEMO-02') { return [null, { payload: text }]; }
return null;

const p = msg.payload;
if (!p || !p.status) { return null; }
const id = msg.topic.split('/')[1];
msg.payload = id + ': ' + p.status + ' · terminal ' + p.terminalId +
    ' · reported ' + (p.reportedAt || 'no date (Will)') +
    ' · received ' + new Date().toLocaleTimeString('es-ES', { timeZone: 'Europe/Madrid' });
return msg;

msg.method = 'GET';
msg.url = 'http://api:8000/sync?scope=vehicle&vehicleId=BUS-DEMO-01';
msg.headers = { 'Authorization': 'Bearer demo-operador-1' };
delete msg.payload;
return msg;

const snap = msg.payload;
if (msg.statusCode !== 200 || !snap || !snap.trip) {
    node.status({ fill: 'red', shape: 'ring', text: 'sync failed: ' + msg.statusCode });
    return null;
}
let st = flow.get('b04');
if (!st || st.tripId !== snap.trip.id) {
    st = { tripId: snap.trip.id, tripState: snap.trip.state, lastPassed: snap.trip.lastPassedSequence, reqs: {}, seen: [] };
} else {
    st.tripState = (st.tripState === 'ENDED') ? 'ENDED' : snap.trip.state;
    st.lastPassed = Math.max(st.lastPassed, snap.trip.lastPassedSequence);
}
for (const r of snap.requests) {
    if (r.tripId !== snap.trip.id) { continue; }
    const cur = st.reqs[r.id];
    const received = Boolean((cur && cur.received) || r.received);
    if (!cur || r.version > cur.version) { st.reqs[r.id] = Object.assign({}, r, { received: received }); }
    else { cur.received = received; }
}
flow.set('b04', st);
node.status({ fill: 'green', shape: 'dot', text: 'sync ok' });
return msg;

const e = msg.payload;
const st = flow.get('b04');
if (!e || e.schemaVersion !== 3 || typeof e.eventType !== 'string' || !st) { return null; }
if (st.seen.indexOf(e.eventId) >= 0) { return null; }
st.seen.push(e.eventId);
if (st.seen.length > 200) { st.seen.shift(); }
if (e.tripId !== st.tripId) { flow.set('b04', st); return [null, { payload: 'resync' }]; }
if (e.eventType === 'request.receipt_recorded') {
    const cur = st.reqs[e.requestId];
    if (!cur) { flow.set('b04', st); return [null, { payload: 'resync' }]; }
    cur.received = true;
} else if (e.eventType.indexOf('request.') === 0 && e.payload && e.payload.id) {
    const r = e.payload;
    const cur = st.reqs[r.id];
    const received = Boolean((cur && cur.received) || r.received);
    if (!cur || r.version > cur.version) { st.reqs[r.id] = Object.assign({}, r, { received: received }); }
    else { cur.received = received; }
} else if (e.eventType === 'trip.progressed') {
    st.lastPassed = Math.max(st.lastPassed, e.payload.lastPassedSequence);
} else if (e.eventType === 'trip.ended') {
    st.tripState = 'ENDED';
}
flow.set('b04', st);
return [{ payload: 'render' }, null];

const st = flow.get('b04');
const when = new Date().toLocaleTimeString('es-ES', { timeZone: 'Europe/Madrid' });
if (!st) { msg.payload = { trip: 'No trip data yet · ' + when, rows: [] }; return msg; }
const rows = Object.values(st.reqs)
    .sort(function (a, b) { return a.sequence - b.sequence; })
    .map(function (r) {
        return {
            id: r.id, line: 'Stop ' + r.physicalStopCode + ' · visit ' + r.sequence + ' · ' + r.state +
                ' · received: ' + (r.received ? 'yes' : 'no') + ' · v' + r.version
        };
    });
msg.payload = {
    trip: 'Trip ' + st.tripId.slice(0, 8) + ' · ' + st.tripState +
        ' · last stop passed: ' + st.lastPassed + ' · updated ' + when, rows: rows
};
return msg;

msg.method = 'POST';
msg.url = 'http://api:8000/demo/reset';
msg.headers = {
    'Authorization': 'Bearer demo-operador-1',
    'Idempotency-Key': 'reset-' + Date.now() + '-' + Math.random().toString(16).slice(2)
};
msg.payload = '';
return msg;

if (msg.statusCode === 200 && msg.payload && msg.payload.trip) {
    flow.set('b04', undefined);
    return [{ payload: 'Reset OK · new trip ' + msg.payload.trip.id.slice(0, 8) + ' · ' + new Date().toLocaleTimeString('es-ES', { timeZone: 'Europe/Madrid' }) }, { payload: 'resync' }];
}
return [{ payload: 'Reset failed: HTTP ' + msg.statusCode }, null];

// Physical ramp node (ESP32): its state for the dashboard, and commands in lab test mode.
const s = flow.get('labRamp') || {};
const t = msg.topic || '';
const p = msg.payload || {};
const now = Date.now();

if (t === 'devices/ramp-esp32-01/status') { s.status = p.status; }
else if (t === 'devices/ramp-esp32-01/ramps/ramp-phys-01') { s.motion = p.motion; s.result = p.lastResult; }
else if (t === 'telemetry/vehicles/BUS-DEMO-01/ramp') {
    if (p.nodeId !== 'ramp-phys-01') { return null; }   // the simulator uses the same topic
    s.stowed = p.stowedLimit; s.deployed = p.deployedLimit; s.at = now;
}
else if (t === 'vehicles/BUS-DEMO-01/presence') {
    s.hmi = p.status;
    if (p.status === 'online') { s.test = false; }   // the driver's HMI takes over
}
else if (msg.test !== undefined) { s.test = msg.test && s.hmi !== 'online'; }

// Same rules as the HMI ramp card: no data for 15 s, both limits ON or moving lock the maneuvers.
const fresh = now - (s.at || 0) <= 15000;
const position = !fresh ? 'NO DATA' : s.stowed && s.deployed ? 'CONFLICT'
    : s.stowed ? 'STOWED' : s.deployed ? 'DEPLOYED' : 'INTERMEDIATE';
const moving = s.motion === 'DEPLOYING' || s.motion === 'STOWING';
const armed = Boolean(s.test) && s.hmi !== 'online' && s.status === 'online';
const canMove = armed && fresh && !moving && position !== 'CONFLICT';
const allowed = { DEPLOY: canMove && position !== 'DEPLOYED', STOW: canMove && position !== 'STOWED', STOP: armed };

// Checked here too, so a click from an old page does not get through.
let command = null;
if (msg.action && allowed[msg.action]) {
    command = { payload: { schemaVersion: 3, commandId: 'lab-test-' + now, action: msg.action } };
}
flow.set('labRamp', s);
const ramp = [s.status || 'no report', position, s.motion].filter(Boolean).join(' · ');
return [{ payload: { ramp: ramp, hmi: s.hmi || 'no report', result: s.result || '-',
    test: Boolean(s.test), allowed: allowed } }, command];
